const RISK = { read_docs: "low", send_email: "high", delete_records: "critical" };

async function runTool(call: ToolCall, ctx: AgentContext) {
  const level = RISK[call.name] ?? "critical"; // unknown tool = deny by default
  audit.log({ agent: ctx.agentId, tool: call.name, level });

  if (level === "critical" && ctx.env === "prod") {
    return deny("blocked in production");
  }
  if (level !== "low") {
    const approved = await approvals.request(ctx.owner, call); // human in the loop
    if (!approved) return deny("not approved");
  }
  return tools[call.name](call.args, ctx.scopedToken); // least privilege
}
